#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
#include <climits>
#include <array>
using namespace std;

using i64 = long long;
using pii = pair<int, int>;

constexpr int dirX[4] = { -1, 1, 0, 0 };
constexpr int dirY[4] = { 0, 0, -1, 1 };

struct edg {
    int src;
    int dst;
    i64 limit;
    i64 used;
    edg(int a, int b, i64 c) : src(a), dst(b), limit(c), used(0) {}
};

class maxflow {
public:
    const i64 big = 1000000000000000000LL;
    int vertexCount;
    int srcNode;
    int dstNode;
    vector<edg> edgeList;
    vector<vector<int>> neighborList;
    vector<int> depth;
    vector<int> iter;
    queue<int> bfsQueue;

    maxflow(int v, int s, int t) : vertexCount(v), srcNode(s), dstNode(t) {
        neighborList.resize(v);
        depth.resize(v);
        iter.resize(v);
    }

    void addConnection(int u, int v, i64 cap) {
        edgeList.emplace_back(u, v, cap);
        edgeList.emplace_back(v, u, 0);
        neighborList[u].push_back(edgeList.size() - 2);
        neighborList[v].push_back(edgeList.size() - 1);
    }

    bool levelGraph() {
        fill(depth.begin(), depth.end(), -1);
        depth[srcNode] = 0;
        bfsQueue.push(srcNode);
        while (!bfsQueue.empty()) {
            int u = bfsQueue.front(); bfsQueue.pop();
            for (int id : neighborList[u]) {
                auto& e = edgeList[id];
                if (e.limit - e.used > 0 && depth[e.dst] == -1) {
                    depth[e.dst] = depth[u] + 1;
                    bfsQueue.push(e.dst);
                }
            }
        }
        return depth[dstNode] != -1;
    }

    i64 sendFlow(int v, i64 flowSoFar) {
        if (v == dstNode) return flowSoFar;
        for (int& i = iter[v]; i < (int)neighborList[v].size(); ++i) {
            int id = neighborList[v][i];
            auto& e = edgeList[id];
            if (depth[e.dst] == depth[v] + 1 && e.limit - e.used > 0) {
                i64 flow = sendFlow(e.dst, min(flowSoFar, e.limit - e.used));
                if (flow > 0) {
                    e.used += flow;
                    edgeList[id ^ 1].used -= flow;
                    return flow;
                }
            }
        }
        return 0;
    }

    i64 computeMaxFlow() {
        i64 result = 0;
        while (levelGraph()) {
            fill(iter.begin(), iter.end(), 0);
            i64 pushed;
            while ((pushed = sendFlow(srcNode, big)) > 0) {
                result += pushed;
            }
        }
        return result;
    }
};

int gridSize, timeBound;
string land[15];
string demand[15];
int shortestTime[15][15];

bool withinBounds(int r, int c) {
    return r >= 0 && r < gridSize && c >= 0 && c < gridSize && land[r][c] != 'Y' && land[r][c] != 'Z';
}

void expandFromZ(int startX, int startY) {
    memset(shortestTime, -1, sizeof(shortestTime));
    queue<pii> q;
    q.push({startX, startY});
    shortestTime[startX][startY] = 0;
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dirX[k], ny = y + dirY[k];
            if (withinBounds(nx, ny) && shortestTime[nx][ny] == -1) {
                shortestTime[nx][ny] = shortestTime[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    for (int i = 0; i < gridSize; ++i)
        for (int j = 0; j < gridSize; ++j)
            if (shortestTime[i][j] == -1) shortestTime[i][j] = 1000000000;
}

int cache[65][12][12][12][12];
bool precomputed[65][12][12][12][12];

bool pathExists(int step, int r1, int c1, int r2, int c2) {
    if (shortestTime[r1][c1] < step) return false;
    if (r1 == r2 && c1 == c2) return true;
    if (step >= timeBound) return false;
    if (shortestTime[r1][c1] <= step) return false;
    if (precomputed[step][r1][c1][r2][c2]) return cache[step][r1][c1][r2][c2];
    precomputed[step][r1][c1][r2][c2] = true;
    for (int d = 0; d < 4; ++d) {
        int nr = r1 + dirX[d], nc = c1 + dirY[d];
        if (nr < 0 || nr >= gridSize || nc < 0 || nc >= gridSize) continue;
        if (land[nr][nc] == 'Y' || land[nr][nc] == 'Z') continue;
        if (pathExists(step + 1, nr, nc, r2, c2)) {
            cache[step][r1][c1][r2][c2] = 1;
            return true;
        }
    }
    cache[step][r1][c1][r2][c2] = 0;
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    memset(cache, -1, sizeof(cache));
    cin >> gridSize >> timeBound;
    for (int i = 0; i < gridSize; ++i) cin >> land[i];
    for (int i = 0; i < gridSize; ++i) cin >> demand[i];

    for (int i = 0; i < gridSize; ++i) {
        for (int j = 0; j < gridSize; ++j) {
            if (land[i][j] == 'Z') {
                expandFromZ(i, j);
                goto nextStep;
            }
        }
    }
nextStep:

    vector<pii> supply, capacity;
    for (int i = 0; i < gridSize; ++i)
        for (int j = 0; j < gridSize; ++j)
            if (land[i][j] != 'Z' && land[i][j] != 'Y' && land[i][j] != '0')
                supply.push_back({i, j});
    for (int i = 0; i < gridSize; ++i)
        for (int j = 0; j < gridSize; ++j)
            if (demand[i][j] != 'Z' && demand[i][j] != 'Y' && demand[i][j] != '0')
                capacity.push_back({i, j});

    int nodeCount = supply.size() + capacity.size() + 2;
    maxflow solver(nodeCount, 0, nodeCount - 1);

    for (int i = 0; i < supply.size(); ++i) {
        i64 val = land[supply[i].first][supply[i].second] - '0';
        solver.addConnection(0, i + 1, val);
    }
    for (int i = 0; i < capacity.size(); ++i) {
        i64 val = demand[capacity[i].first][capacity[i].second] - '0';
        solver.addConnection(supply.size() + 1 + i, nodeCount - 1, val);
    }

    for (int i = 0; i < supply.size(); ++i)
        for (int j = 0; j < capacity.size(); ++j)
            if (pathExists(0, supply[i].first, supply[i].second, capacity[j].first, capacity[j].second))
                solver.addConnection(i + 1, supply.size() + 1 + j, 10000000LL);

    cout << solver.computeMaxFlow() << '\n';
    return 0;
}
